(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,source)=>({origin,prefix:null,root:null,suffix:null,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("secular",{etymology:E("From Latin saecularis ‘of an age or generation’, from saeculum ‘age, world’; it came to mean worldly or nonreligious, and can describe life outside a religious order.","https://www.etymonline.com/word/secular"),contexts:[C("secular.s1","教育","The city school follows a secular curriculum and does not teach the doctrines of any church.","这所市立学校采用世俗课程，不教授任何教会教义。","Secular means not religious or not controlled by a church.","And links two ways the curriculum is independent of church authority.","This is the nonreligious-institution sense.") ,C("secular.s2","生活","After leaving the monastery, the former monk returned to secular life in an ordinary town.","离开修道院后，这位前僧侣回到世俗生活，在普通城镇定居。","Secular life is ordinary worldly life outside a religious order.","After gives the transition from monastery to ordinary society.","This is the everyday-world sense.")],mistakes:[M("meaning","The secular school was governed by the church and taught only its religious doctrine.","The secular school was independent of church control and did not teach a church's doctrine.","Secular describes a nonreligious or church-independent institution, not one controlled by a church.")],quiz:[Q("secular.q1","secular.s1","meaning","A secular public school is generally ___.",["not controlled by a church","run as a monastery","required to teach one church's doctrine"],"not controlled by a church","This is the institutional meaning.","meaning"),Q("secular.q2","secular.s2","context","A person who leaves a religious order for secular life returns to ___.",["ordinary life in the wider world","a stricter monastic order","a geometry class"],"ordinary life in the wider world","This is the everyday-world sense.","context"),Q("secular.q3","secular.s1","collocation","The museum is a ____ institution and is not governed by a religious body.",["secular","sedentary","sedimentary"],"secular","A secular institution is not under church control.","collocation"),Q("secular.q4","secular.s2","distinction","Which situation best illustrates secular rather than monastic life?",["A former nun works in a town library.","A monk remains inside a religious community.","A priest leads a convent's daily service."],"A former nun works in a town library.","She lives in ordinary society outside a religious order.","distinction")]});
D("secure",{etymology:E("From Latin securus ‘free from care, safe’, from se- ‘without’ + cura ‘care’; the adjective means safe or firmly fastened, while the verb can mean obtain or make safe.","https://www.etymonline.com/word/secure"),contexts:[C("secure.s1","網路","Use a secure connection before entering your bank password so other people cannot intercept it.","输入银行密码前请使用安全连接，以免他人截取。","Secure means safe from danger, harm, or loss.","Before marks the precaution taken prior to entering sensitive information.","This is the protected-from-danger adjective.") ,C("secure.s2","居家","The caretaker secured the gate with a heavy bolt so it would not swing open in the wind.","看护人用粗大的插销闩好大门，防止它被风吹开。","Secure can mean fasten something firmly so it will not move or open.","With a heavy bolt names the fastening method.","This is the firmly-fastened sense.") ,C("secure.s3","工作","After three interviews, Lena secured a research position at the university.","经过三轮面试，莉娜成功获得了大学的研究职位。","To secure something important is to succeed in getting it.","After three interviews gives the effort that led to success.","This is the obtain-a-position verb sense.") ,C("secure.s4","安全","The crew secured the ladder to the roof before anyone climbed it.","有人爬上梯子前，工作人员先把梯子牢固地固定在屋顶上。","To secure an object is to make it safe or fasten it in place.","Before anyone climbed it shows the safety purpose.","This is the action of making an object stable.")],mistakes:[M("meaning","The crew secured the ladder by leaving it loose against the wall where it could slide away.","The crew secured the ladder by fastening it firmly so it could not slide away.","To secure something is to make it safe or fasten it firmly, not leave it unstable.")],quiz:[Q("secure.q1","secure.s1","meaning","A secure password is one that is ___.",["protected against unauthorized access","easy for strangers to guess","left written on a public sign"],"protected against unauthorized access","This is the safe-from-harm adjective sense.","meaning"),Q("secure.q2","secure.s2","context","A bolt secures a gate when it ___.",["fastens the gate so it cannot swing open","helps someone win a job","makes a password easy to guess"],"fastens the gate so it cannot swing open","This is the firmly-fastened sense.","context"),Q("secure.q3","secure.s3","meaning","She secured a scholarship means she ___.",["successfully obtained one","locked it to a wall","made it unsafe"],"successfully obtained one","Secure as a verb can mean succeed in getting something.","meaning"),Q("secure.q4","secure.s4","collocation","Before the storm, the workers ____ the loose roof panels.",["secured","secluded","seethed"],"secured","They fastened the panels so they would stay in place.","collocation")]});
D("securely",{etymology:E("From secure + adverb-forming -ly; secure comes from Latin securus ‘safe, free from care’. Securely describes a firm, safe, or confident manner.","https://www.etymonline.com/word/securely"),contexts:[C("securely.s1","居家","The child seat was securely fastened to the back seat, with both straps tight and locked.","儿童座椅被牢牢固定在后座上，两条带子都已拉紧并锁好。","Securely means firmly and safely, so something is unlikely to move or fail.","Tight and locked specify why the fastening is firm.","This is the firmly-fastened adverb use.")],mistakes:[M("meaning","The lid was securely attached even though one loose hinge let it fall off at every bump.","The lid was securely attached with every hinge tight enough to keep it in place.","Securely means firmly and safely, not loosely attached in a way that can fail.")],quiz:[Q("securely.q1","securely.s1","meaning","The package was tied securely, so it was tied ___.",["firmly enough not to come loose","with a knot that was already undone","in a way that exposed it to danger"],"firmly enough not to come loose","This is the firm-and-safe adverbial sense.","meaning"),Q("securely.q2","securely.s1","context","A ladder attached securely to a roof is ___.",["fastened firmly and safely","balanced loosely on one rung","hidden in a drawer"],"fastened firmly and safely","The adverb tells how the ladder is attached.","context"),Q("securely.q3","securely.s1","collocation","Please store the records ____ in the locked cabinet.",["securely","secondarily","secluded"],"securely","Store securely means keep protected from loss or access.","collocation"),Q("securely.q4","securely.s1","distinction","Which object is fixed securely?",["A bolt is tightened and the shelf no longer wobbles.","A screw turns freely and the shelf falls.","A box is left open in the rain."],"A bolt is tightened and the shelf no longer wobbles.","Firm fastening prevents movement.","distinction")]});
D("security",{etymology:E("From Latin securitas ‘freedom from care, safety’, from securus ‘safe’; English security names protection from danger or worry and an asset or pledge held to ensure a debt or promise.","https://www.etymonline.com/word/security"),contexts:[C("security.s1","保安","Airport security checked every bag before passengers entered the departure area.","乘客进入候机区前，机场安保人员检查了每一件行李。","Security is protection from danger or the people and measures providing it.","Checked every bag shows the protective measures.","This is the protection-and-safeguards sense.") ,C("security.s2","金融","The lender held the house title as security until the borrower repaid the loan.","借款人还清贷款前，贷款方把房屋产权文件作为担保持有。","Security can be something held as a pledge to ensure a debt is fulfilled.","Until marks how long the pledge is held.","This is the collateral sense.")],mistakes:[M("meaning","The bank released the security before the borrower signed any promise to repay the loan.","The bank held the security until the borrower fulfilled the promise to repay the loan.","In a loan, security is held as a pledge to ensure repayment.")],quiz:[Q("security.q1","security.s1","meaning","Airport security is intended to provide ___.",["protection from danger","a second copy of a book","a sediment layer"],"protection from danger","This is the safety-and-protection sense.","meaning"),Q("security.q2","security.s2","context","A lender may hold a property title as security because it ___.",["serves as a pledge for repayment","is a public announcement","is a religious group"],"serves as a pledge for repayment","This is the collateral sense.","context"),Q("security.q3","security.s1","collocation","The airport increased ____ after a credible threat was reported.",["security","sedulity","seclusion"],"security","Airport security refers to protective measures.","collocation"),Q("security.q4","security.s2","distinction","Which item is being used as security for a loan?",["A deed is pledged until the debt is repaid.","A guard checks visitors at the entrance.","A camera records the lobby."],"A deed is pledged until the debt is repaid.","The deed is collateral held to ensure repayment.","distinction")]});
D("sedate",{etymology:E("From Latin sedatus, past participle of sedare ‘settle, calm’, from sedere ‘sit’; the adjective means calm and unhurried, while the verb means administer a calming drug.","https://www.etymonline.com/word/sedate"),contexts:[C("sedate.s1","社交","The reception had a sedate atmosphere, with quiet music and a small group speaking calmly.","招待会气氛平和，音乐轻柔，来宾三三两两地平静交谈。","Sedate as an adjective means calm, slow, and unhurried in behavior.","Quiet music and calm speech establish the unhurried mood.","This is the calm-temperament adjective.") ,C("sedate.s2","醫療","Before the short procedure, the anesthetist sedated the patient so she could relax under medical supervision.","短暂操作前，麻醉医师在医疗监护下给病人使用了镇静药，让她放松下来。","To sedate someone is to give a drug that makes the person calm, relaxed, or unconscious.","Before places the medication before the procedure; under supervision gives the clinical setting.","This is the medical verb sense.")],mistakes:[M("meaning","The anesthetist sedated the patient by giving her a stimulant that made her more alert and restless.","The anesthetist sedated the patient with a medicine that made her calmer under supervision.","Sedate as a verb means use a calming drug, not a stimulant that increases alertness.")],quiz:[Q("sedate.q1","sedate.s1","meaning","A sedate evening is usually ___.",["calm and unhurried","wildly noisy and rushed","medically unconscious"],"calm and unhurried","This is the adjective sense.","meaning"),Q("sedate.q2","sedate.s2","context","A doctor may sedate a patient before a procedure by ___.",["giving a medicine that calms the patient","asking the patient to sprint","locking the patient in a room"],"giving a medicine that calms the patient","This is the medical verb use.","context"),Q("sedate.q3","sedate.s1","collocation","The concert opened with a ____ instrumental piece rather than a loud march.",["sedate","sedimentary","secreted"],"sedate","Sedate can describe a calm, restrained mood.","collocation"),Q("sedate.q4","sedate.s2","distinction","Which sentence uses sedate as a verb?",["The clinician sedated the patient before the examination.","The ceremony was sedate and quiet.","The audience preferred a sedate pace."],"The clinician sedated the patient before the examination.","Here sedated describes the action of giving a calming drug.","distinction")]});D("sedentary",{etymology:E("From Latin sedentarius ‘sitting’, from sedere ‘sit’; sedentary first described sitting or remaining in one place and now also refers to a lifestyle involving little exercise.","https://www.etymonline.com/word/sedentary"),contexts:[C("sedentary.s1","健康","Because she worked at a desk all day, she added a walk at lunch to offset her sedentary routine.","由于她整天伏案工作，便在午休时散步，以弥补久坐少动的日常。","A sedentary routine involves much sitting and little physical activity.","At a desk all day explains why the routine is sedentary.","This is the low-activity lifestyle sense.") ,C("sedentary.s2","生態","The island's sedentary bird population stays in the same valley throughout the year instead of migrating.","岛上的留居鸟群全年待在同一山谷，不会迁徙。","Sedentary can mean staying in one place rather than moving about.","Throughout the year and instead of migrating show the lack of movement.","This is the fixed-location sense.")],mistakes:[M("meaning","A sedentary lifestyle consists of running several kilometers every morning and playing sports all afternoon.","A sedentary lifestyle involves long periods of sitting and little exercise.","Sedentary describes low movement and much sitting, not vigorous daily activity.")],quiz:[Q("sedentary.q1","sedentary.s1","meaning","A sedentary job usually involves ___.",["long periods of sitting","constant heavy exercise","annual migration"],"long periods of sitting","This is the lifestyle sense.","meaning"),Q("sedentary.q2","sedentary.s2","context","A sedentary species stays ___.",["in one place rather than moving around","in the air at all times","only at a desk"],"in one place rather than moving around","This is the fixed-location sense.","context"),Q("sedentary.q3","sedentary.s1","collocation","Desk workers can reduce the risks of a ____ lifestyle by taking regular walks.",["sedentary","secluded","seismic"],"sedentary","A sedentary lifestyle has too much sitting and too little movement.","collocation"),Q("sedentary.q4","sedentary.s2","distinction","Which animal group is sedentary?",["A population that remains in one valley year-round","A flock that migrates between continents","A herd that moves to a new pasture each week"],"A population that remains in one valley year-round","It stays in one place instead of moving seasonally.","distinction")]});
D("sedge",{etymology:E("From Old English secg, a Germanic plant name; sedge denotes a grasslike wetland plant, typically with a solid three-sided stem.","https://www.etymonline.com/word/sedge"),contexts:[C("sedge.s1","濕地","A sedge grew at the pond's edge, its triangular stem rising above the shallow water.","池塘边长着莎草，三棱茎从浅水中伸出。","Sedge is a grasslike wetland plant, often recognized by its solid, three-sided stem.","At the pond's edge and above shallow water establish its wetland habitat.","This is the botanical plant sense.")],mistakes:[M("meaning","The botanist identified the tall grasslike wetland plant with a solid triangular stem as a desert cactus.","The botanist identified the grasslike wetland plant with a solid triangular stem as a sedge.","A sedge is a grasslike wetland plant, not a desert cactus.")],quiz:[Q("sedge.q1","sedge.s1","meaning","A sedge is a plant commonly found ___.",["in wet places","on dry desert dunes only","inside a deep ocean trench"],"in wet places","Sedges are grasslike wetland plants.","meaning"),Q("sedge.q2","sedge.s1","context","The botanist examined the sedge's stem because it was ___.",["solid and three-sided","hollow and perfectly round","made of stone"],"solid and three-sided","That stem shape is characteristic of sedges.","context"),Q("sedge.q3","sedge.s1","collocation","At the marsh edge, clumps of ____ grew among the reeds.",["sedge","secretin","secondhand"],"sedge","Sedge is a wetland plant that can grow with reeds.","collocation"),Q("sedge.q4","sedge.s1","meaning","Which plant is most likely a sedge?",["A grasslike plant with a solid three-sided stem in a marsh","A cactus with thick spines on a dry dune","A pine tree on a mountain"],"A grasslike plant with a solid three-sided stem in a marsh","The habitat and stem match the botanical definition.","meaning")]});
D("sediment",{etymology:E("From Latin sedimentum ‘a settling’, from sedere ‘sit’; sediment is material that settles at the bottom of a liquid or deposits laid down by water, ice, or wind.","https://www.etymonline.com/word/sediment"),contexts:[C("sediment.s1","實驗","After the muddy water stood overnight, a layer of sediment had settled at the bottom of the jar.","泥水静置一夜后，一层沉淀物落在了罐底。","Sediment is solid material that sinks to the bottom of a liquid.","After the water stood overnight explains the settling.","This is the liquid-bottom sense.") ,C("sediment.s2","地質","The river carried sediment downstream and deposited sand and silt along the floodplain.","河水把沉积物带往下游，并将沙和粉砂堆积在泛滥平原上。","Sediment can be mud, sand, or stones laid down by water, ice, or wind.","Carried and deposited describe transport and laying down by water.","This is the geological-deposit sense.")],mistakes:[M("meaning","The clear liquid contained sediment floating permanently above its surface and never settling or being deposited.","The liquid contained sediment that settled at the bottom, while river sediment could be deposited in layers.","Sediment is solid material that settles or is laid down, not material that remains permanently above the liquid.")],quiz:[Q("sediment.q1","sediment.s1","meaning","The sediment at the bottom of a jar is ___.",["solid particles that have sunk through the liquid","the clear liquid above them","a plant with a three-sided stem"],"solid particles that have sunk through the liquid","This is the material-settling-in-liquid sense.","meaning"),Q("sediment.q2","sediment.s2","context","A river deposits sediment when it leaves behind ___.",["mud, sand, or stones","only dissolved sunlight","a secret message"],"mud, sand, or stones","This is the geological material carried by water.","context"),Q("sediment.q3","sediment.s1","collocation","Let the water stand until the ____ settles to the bottom.",["sediment","sedate","sector"],"sediment","Sediment settles out of a liquid.","collocation"),Q("sediment.q4","sediment.s2","distinction","Which is geological sediment?",["Sand deposited by a river on its floodplain","A hormone released by a gland","A school division after primary level"],"Sand deposited by a river on its floodplain","Water can carry and deposit sand as sediment.","distinction")]});
D("sedimentary",{etymology:E("From sediment + -ary, with sediment from Latin sedimentum ‘a settling’; sedimentary describes rock formed when particles settle and accumulate in layers.","https://www.etymonline.com/word/sedimentary"),contexts:[C("sedimentary.s1","地質","The geologist identified the striped cliff as sedimentary rock because its visible layers formed from settled particles.","地质学家认出这面有条纹的峭壁由沉积岩构成，因为可见的层理是颗粒沉降形成的。","Sedimentary describes rock made from particles that settled in layers.","Because connects the observed layers with their formation.","This is the rock-type adjective sense.")],mistakes:[M("meaning","The geologist called the glassy rock sedimentary even though it cooled directly from molten lava with no deposited layers.","The geologist called the layered rock sedimentary because it formed from particles deposited over time.","Sedimentary rock forms from accumulated particles, not by direct cooling from molten lava.")],quiz:[Q("sedimentary.q1","sedimentary.s1","meaning","Sedimentary rock forms from particles that ___.",["settle and build up in layers","melt into a single glassy mass","remain suspended forever"],"settle and build up in layers","This is the source definition of the adjective.","meaning"),Q("sedimentary.q2","sedimentary.s1","context","A cliff with successive deposited layers may be described as ___.",["sedimentary","secretive","sedate"],"sedimentary","The adjective describes rock formed from layered particles.","context"),Q("sedimentary.q3","sedimentary.s1","word-formation","Sedimentary is built from sediment plus the suffix ___.",["-ary","-less","-hood"],"-ary","The suffix -ary forms an adjective relating to sediment.","word-formation"),Q("sedimentary.q4","sedimentary.s1","distinction","Which rock is sedimentary?",["Rock made from grains deposited in layers","Rock formed by cooling directly from lava","A plant growing in a marsh"],"Rock made from grains deposited in layers","Deposited grains that accumulate in layers define sedimentary rock.","distinction")]});
D("sedimentation",{etymology:E("From sediment + -ation, ultimately from Latin sedimentum ‘a settling’; sedimentation names particles sinking in liquid or sediment accumulating to form layers of rock.","https://www.etymonline.com/word/sedimentation"),contexts:[C("sedimentation.s1","水處理","The treatment tank uses sedimentation to let suspended particles sink before the water is filtered.","处理池利用沉降让悬浮颗粒先下沉，再过滤水。","Sedimentation is the process of solid particles sinking in a liquid.","Before shows that settling precedes filtration.","This is the liquid-particle process sense.") ,C("sedimentation.s2","地質","Over thousands of years, sedimentation built successive layers on the lake bed and eventually formed rock.","数千年来，沉积作用在湖床上形成一层层沉积物，最终变成岩石。","Sedimentation can be the laying down of sediment to form rock layers over time.","Over thousands of years gives the geological timescale.","This is the rock-layer formation sense.")],mistakes:[M("meaning","The water plant called it sedimentation when every particle stayed dissolved and none settled or formed a layer.","The water plant called it sedimentation when suspended particles settled out of the liquid.","Sedimentation requires particles to settle or accumulate, not remain dissolved.")],quiz:[Q("sedimentation.q1","sedimentation.s1","meaning","In a settling tank, sedimentation lets particles ___.",["sink through the liquid","turn into a secret","rise forever without settling"],"sink through the liquid","This is the particle-settling process.","meaning"),Q("sedimentation.q2","sedimentation.s2","context","Geological sedimentation can gradually produce ___.",["layers of rock","a second-hand account","a calm manner"],"layers of rock","Deposited sediment forms layers over time.","context"),Q("sedimentation.q3","sedimentation.s1","collocation","The wastewater plant speeds up ____ before the filtration stage.",["sedimentation","seclusion","sector"],"sedimentation","Sedimentation removes suspended particles by letting them settle.","collocation"),Q("sedimentation.q4","sedimentation.s2","distinction","Which example describes geological sedimentation?",["Mud accumulates in layers on a lake bed over centuries.","Particles settle at the bottom of a jar overnight.","A gland releases a hormone into the intestine."],"Mud accumulates in layers on a lake bed over centuries.","This is the long-term laying down of sediment to form layers.","distinction")]});D("seduce",{etymology:E("From Latin seducere ‘lead aside’, from se- ‘aside’ + ducere ‘lead’; English developed the senses of persuading someone into sex or enticing someone to do something inadvisable.","https://www.etymonline.com/word/seduce"),contexts:[C("seduce.s1","文學","In the novel, the prince tried to seduce the heroine, but she refused and made her own choice.","小说中，王子试图引诱女主角与他发生关系，但她拒绝了并作出自己的选择。","To seduce can mean persuade someone to have sex.","Tried to and refused make clear the attempted persuasion without implying consent.","This is the sexual-persuasion sense, described non-graphically.") ,C("seduce.s2","消費","The advertisement seduced shoppers into buying an unnecessary upgrade by promising features they would never use.","广告承诺一些顾客永远用不到的功能，诱使他们购买并不需要的升级。","To seduce someone can mean persuade or tempt them to do something they should not do.","Into buying and unnecessary identify the tempting but unwise action.","This is the broader temptation sense.")],mistakes:[M("meaning","The tempting advertisement seduced customers by warning them away from the unnecessary purchase.","The tempting advertisement seduced customers into making the unnecessary purchase.","Seduce means entice or persuade toward an action, not discourage someone from it.")],quiz:[Q("seduce.q1","seduce.s1","meaning","In a novel, one character tries to seduce another when trying to ___.",["persuade the person to have sex","keep the person apart from everyone","make the person more alert with a stimulant"],"persuade the person to have sex","This is one dictionary sense; it does not imply that persuasion succeeds.","meaning"),Q("seduce.q2","seduce.s2","context","A flashy offer seduced him into overspending, meaning it ___.",["tempted him to do something unwise","stopped him from spending","secured his savings"],"tempted him to do something unwise","This is the broader temptation sense.","context"),Q("seduce.q3","seduce.s2","collocation","The ad tried to ____ buyers into paying for features they did not need.",["seduce","secrete","seclude"],"seduce","Seduce someone into doing something is the relevant pattern.","collocation"),Q("seduce.q4","seduce.s1","register","In reporting a real person's experience, writers should use seduce carefully because it can imply ___.",["sexual persuasion or enticement","a neutral school section","a geological layer"],"sexual persuasion or enticement","The word has a sensitive sexual sense and should be precise.","register")]});
D("sedulity",{etymology:E("From Latin sedulitas ‘diligence’, from sedulus ‘diligent’; the uncommon English noun means steady, attentive application to work.","https://www.etymonline.com/word/sedulity"),contexts:[C("sedulity.s1","研究","Her sedulity showed in the careful notes she kept each day while checking hundreds of archive records.","她每天核对数百份档案并认真做笔记，显出了持之以恒的勤勉。","Sedulity is the quality of working steadily and attentively.","Each day and careful notes give evidence of sustained attention.","This is the uncommon noun for diligence.")],mistakes:[M("meaning","The student's sedulity was evident because he ignored the research and left every record unchecked.","The student's sedulity was evident because he checked each record carefully and consistently.","Sedulity means steady, attentive effort, not neglecting the task.")],quiz:[Q("sedulity.q1","sedulity.s1","meaning","Sedulity is ___.",["steady and attentive effort","a lack of interest in work","the process of a liquid freezing"],"steady and attentive effort","This is the noun's definition.","meaning"),Q("sedulity.q2","sedulity.s1","context","A researcher shows sedulity by ___.",["checking each source carefully day after day","skipping every reference","guessing without reading"],"checking each source carefully day after day","Consistency and care demonstrate the quality.","context"),Q("sedulity.q3","sedulity.s1","word-formation","Sedulity is related to sedulous, meaning ___.",["diligent and attentive","transparent","fixed in one place"],"diligent and attentive","The related adjective carries the same diligence idea.","word-formation"),Q("sedulity.q4","sedulity.s1","distinction","Which worker demonstrates sedulity?",["A lab assistant records every measurement with care each day.","A worker leaves samples unlabeled and walks away.","A visitor hides a key under a mat."],"A lab assistant records every measurement with care each day.","The repeated careful work is steady and attentive.","distinction")]});
D("sedulous",{etymology:E("From Latin sedulus ‘diligent, assiduous’; sedulous describes applying steady care and attention, especially to detailed work.","https://www.etymonline.com/word/sedulous"),contexts:[C("sedulous.s1","手工","The sedulous archivist checked every date against the original letters before cataloging them.","这位勤勉的档案管理员在编目之前，逐一对照原信核实每个日期。","Sedulous means working steadily and attentively, often on a detailed task.","Every date and before cataloging show careful, repeated checking.","This is the diligent-work adjective.")],mistakes:[M("meaning","The sedulous editor glanced at one page and ignored the hundreds of unverified references.","The sedulous editor checked the references carefully and consistently throughout the manuscript.","Sedulous describes sustained careful attention, not a cursory glance.")],quiz:[Q("sedulous.q1","sedulous.s1","meaning","A sedulous worker is ___.",["diligent and attentive","careless and inattentive","hidden from view"],"diligent and attentive","This is the adjective's meaning.","meaning"),Q("sedulous.q2","sedulous.s1","context","The sedulous proofreader ___.",["checks each line carefully","skips the text entirely","reads only the title"],"checks each line carefully","Detailed, careful work is sedulous.","context"),Q("sedulous.q3","sedulous.s1","collocation","The team made a ____ review of every footnote before publication.",["sedulous","seedy","secondhand"],"sedulous","A sedulous review is attentive and thorough.","collocation"),Q("sedulous.q4","sedulous.s1","distinction","Which is a sedulous approach to cataloging?",["Verifying each entry against the source one by one","Copying titles without checking them","Leaving the records in random piles"],"Verifying each entry against the source one by one","The approach is steady and careful.","distinction")]});
D("see",{etymology:E("From Old English seon, from Proto-Germanic sehan; English see covers visual perception, understanding, meeting or visiting someone, and making sure an event happens.","https://www.etymonline.com/word/see"),contexts:[C("see.s1","觀察","From the hill, we could see the harbor lights through the fog.","从山上透过雾气，我们能看见港口的灯光。","To see is to notice someone or something with the eyes.","Through the fog describes the visual conditions.","This is the visual-perception sense.") ,C("see.s2","理解","I see why the numbers do not match now that you have shown me the missing entry.","你指出遗漏的一项后，我现在明白这些数字为何对不上了。","To see can mean understand something.","Why introduces the point that has become clear.","This is the understanding sense.") ,C("see.s3","會面","The advisor will see each student for ten minutes after the lecture.","讲座结束后，导师会逐个与每位学生面谈十分钟。","To see someone can mean visit or meet that person.","Each student and after the lecture describe an arranged meeting.","This is the meeting sense.") ,C("see.s4","安排","Please see that every lab sample is labeled before it is stored.","请确保每份实验室样本在存放前都贴好标签。","To see that something happens means make sure it is done.","That introduces the required outcome.","This is the ensure-or-arrange sense.")],mistakes:[M("meaning","The supervisor saw that the samples were labeled by ignoring the labels and storing them unlabeled.","The supervisor saw that the samples were labeled by checking each one before storage.","See that means make sure something happens, so the action must ensure the labels are present.")],quiz:[Q("see.q1","see.s1","meaning","From the lookout, we could see the lighthouse means we could ___.",["notice it with our eyes","understand a difficult rule","meet the lighthouse keeper"],"notice it with our eyes","This is the visual sense.","meaning"),Q("see.q2","see.s2","context","When she says “I see the problem now,” she means she ___.",["understands it","visits it","looks at it from a distance only"],"understands it","See can mean understand.","context"),Q("see.q3","see.s3","meaning","The doctor will see a patient at noon means the doctor will ___.",["meet or attend to the patient","make the patient visible","ensure noon occurs"],"meet or attend to the patient","This is the visit-or-meeting sense.","meaning"),Q("see.q4","see.s4","collocation","Please ____ that the door is locked before you leave.",["see","sedate","secrete"],"see","See that means make sure.","collocation")]});
D("see-through",{etymology:E("A compound of see + through, see from Old English seon and through from Old English þurh; the adjective describes thin or clear material that lets light pass so objects behind it remain visible.","https://www.etymonline.com/word/see-through"),contexts:[C("see-through.s1","服飾","The designer added a lining beneath the see-through fabric so the garment would not reveal what was underneath.","设计师在透明面料下面加了衬里，以免衣服透出里面的部分。","See-through material is thin or clear enough for light and sight to pass through it.","So the garment would not reveal what was underneath explains the transparency.","This is the transparent-material adjective.")],mistakes:[M("meaning","The see-through glass blocked all light, so nobody could see the object on the other side.","The see-through glass let light pass, so the object on the other side remained visible.","See-through means light can pass through and objects behind can be seen.")],quiz:[Q("see-through.q1","see-through.s1","meaning","A see-through curtain allows people to ___.",["see shapes or objects behind it","see only the curtain's back","block all light completely"],"see shapes or objects behind it","This describes the transparent material sense.","meaning"),Q("see-through.q2","see-through.s1","context","She wore a lining under a see-through blouse because the cloth was ___.",["transparent enough to reveal what was behind it","thick and completely opaque","a kind of sedimentary rock"],"transparent enough to reveal what was behind it","The adjective describes material through which one can see.","context"),Q("see-through.q3","see-through.s1","collocation","The architect used ____ glass in the upper panels to admit light.",["see-through","sedulous","secluded"],"see-through","See-through glass is transparent.","collocation"),Q("see-through.q4","see-through.s1","distinction","Which screen is see-through?",["A clear panel lets viewers see the room beyond it.","A solid panel blocks every view behind it.","A painted wall admits no light."],"A clear panel lets viewers see the room beyond it.","The transparent panel permits sight through it.","distinction")]});D("seed",{etymology:E("From Old English sæd ‘seed’, from Proto-Germanic *sædiz; English uses seed for a plant's reproductive part, the beginning of a development, and as a verb for planting or removing seeds.","https://www.etymonline.com/word/seed"),contexts:[C("seed.s1","園藝","We planted each seed in a small pot and kept the soil damp until a shoot appeared.","我们把每粒种子种在小盆里，并保持土壤湿润，直到幼芽冒出。","A seed is the small part of a plant from which a new plant grows.","Until a shoot appeared gives the result of planting.","This is the plant-reproduction noun sense.") ,C("seed.s2","比喻","That conversation planted the seed of doubt that eventually changed his decision.","那次谈话埋下了怀疑的种子，最终改变了他的决定。","A seed can be the beginning of a feeling or later development.","Eventually changed traces the development from its beginning.","This is the figurative beginning sense.") ,C("seed.s3","烹飪","Before blending the peppers, she seeded them to remove the bitter seeds.","搅打甜椒前，她先去掉籽，以免带入苦味。","To seed means plant seeds or remove seeds from fruit or vegetables.","Before blending gives the order of preparation.","This is the verb sense of removing seeds.")],mistakes:[M("meaning","The gardener seeded the tray by removing every seed and planting nothing in the soil.","The gardener seeded the tray by placing seeds in the soil so new plants could grow.","To seed a tray for planting means sow seeds in it, not remove all seeds.")],quiz:[Q("seed.q1","seed.s1","meaning","A sunflower grows from a ___.",["seed","sector","secret"],"seed","The seed is the plant part from which it grows.","meaning"),Q("seed.q2","seed.s2","context","The first small success planted a seed of confidence, meaning it ___.",["began a feeling that could grow","removed a plant's reproductive part","became a tree overnight"],"began a feeling that could grow","This is the figurative beginning sense.","context"),Q("seed.q3","seed.s3","meaning","If a cook seeds a pepper, the cook ___.",["removes its seeds","plants it in a field","stores it in a bank"],"removes its seeds","Seed can be a verb meaning remove seeds from food.","meaning"),Q("seed.q4","seed.s1","collocation","The gardener pressed a tomato ____ into the damp soil.",["seed","sedge","sediment"],"seed","A seed is planted in soil to grow a new plant.","collocation")]});
D("seedbed",{etymology:E("A compound of seed + bed, with seed from Old English sæd and bed from Old English bedd; it first names prepared soil for sowing and extends metaphorically to a place where something develops.","https://www.etymonline.com/word/seedbed"),contexts:[C("seedbed.s1","園藝","The gardener raked the seedbed smooth before sowing rows of lettuce.","播种莴苣前，园丁把育苗床耙平。","A seedbed is prepared soil where seeds are planted and grow.","Before sowing gives the preparation sequence.","This is the literal gardening sense.") ,C("seedbed.s2","社會","The abandoned lots became a seedbed for neighborhood disputes as residents argued over who should maintain them.","废弃空地成了社区矛盾滋生的环境，居民开始争论该由谁来维护。","A seedbed is a place or situation where something can develop, often something undesirable.","As residents argued illustrates the conditions in which conflict developed.","This is the figurative environment-for-development sense.")],mistakes:[M("meaning","The neglected lots were a seedbed for cooperation even though nobody met, communicated, or shared any work.","The neglected lots became a seedbed for conflict as residents argued over their upkeep.","Figurative seedbed means a situation that encourages something to develop; the context must support that development.")],quiz:[Q("seedbed.q1","seedbed.s1","meaning","A gardener prepares a seedbed to ___.",["sow seeds in prepared soil","store tools under a bed","remove a plant's leaves"],"sow seeds in prepared soil","This is the literal horticultural sense.","meaning"),Q("seedbed.q2","seedbed.s2","context","Calling poor communication a seedbed for conflict means it ___.",["creates conditions in which conflict can grow","prevents all disagreement","is a place to plant lettuce"],"creates conditions in which conflict can grow","This is the figurative sense.","context"),Q("seedbed.q3","seedbed.s1","collocation","She loosened the soil in the ____ before planting carrots.",["seedbed","secondhand","secretin"],"seedbed","A seedbed is prepared soil for sowing.","collocation"),Q("seedbed.q4","seedbed.s2","distinction","Which is a figurative seedbed?",["A rumor-filled workplace where mistrust spreads","A tray of soil used for seedlings","A field with rows of newly sown beans"],"A rumor-filled workplace where mistrust spreads","The situation encourages mistrust to develop.","distinction")]});
D("seedling",{etymology:E("From seed + the diminutive suffix -ling, with seed from Old English sæd; a seedling is a very young plant and, in forestry, a young tree before it is planted out.","https://www.etymonline.com/word/seedling"),contexts:[C("seedling.s1","園藝","The tomato seedling had two small leaves and needed a larger pot before its roots became crowded.","这株番茄幼苗长出两片小叶子，根系挤满花盆前需要换个大盆。","A seedling is a very young plant that has just grown from a seed.","Two small leaves and its need for a larger pot show an early growth stage.","This is the general young-plant sense.") ,C("seedling.s2","林業","The nursery kept each oak seedling in a protected bed until it was sturdy enough for forest planting.","苗圃把每棵橡树小苗养在防护苗床中，直到它足够健壮，可以种到林地里。","A seedling can be a young tree before it is planted out in a forest or garden.","Until it was sturdy enough describes the stage before transplanting.","This is the young-tree planting-out sense.")],mistakes:[M("meaning","The nursery labeled a 200-year-old oak as a seedling because it had grown from a seed long ago.","The nursery labeled the very young oak as a seedling before it was planted out.","Seedling refers to a young plant or young tree, not a mature tree merely because it once grew from a seed.")],quiz:[Q("seedling.q1","seedling.s1","meaning","A seedling is ___.",["a very young plant","an old tree with a hollow trunk","a seed that has not begun to grow"],"a very young plant","This is the general young-plant definition.","meaning"),Q("seedling.q2","seedling.s2","context","A forestry nursery raises oak seedlings before ___.",["planting the young trees in a forest","harvesting mature timber","drying the seeds for food"],"planting the young trees in a forest","This is the young-tree-before-planting use.","context"),Q("seedling.q3","seedling.s1","word-formation","The ending -ling in seedling helps form a word for ___.",["a young or small thing","a person who manages an office","a place where rocks settle"],"a young or small thing","The suffix can mark a young or small form.","word-formation"),Q("seedling.q4","seedling.s2","distinction","Which plant is most clearly a seedling?",["A young pine kept in a nursery before forest planting","A fallen log decades after a tree died","A packet of dry seeds in a shop"],"A young pine kept in a nursery before forest planting","It is a young tree awaiting planting out.","distinction")]});
D("seedy",{etymology:E("From seed + -y, originally ‘full of seeds’; by figurative extension seedy came to mean shabby, disreputable, or run-down.","https://www.etymonline.com/word/seedy"),contexts:[C("seedy.s1","城市","The seedy hotel had broken signs, stained carpets, and a lobby that no one had repaired for years.","这家破败不体面的旅馆招牌坏了、地毯有污渍，大堂多年无人修缮。","Seedy means shabby, disreputable, and run-down.","Broken signs and unrepaired carpets illustrate the neglected condition.","This is the figurative shabby-place sense.")],mistakes:[M("meaning","The seedy theater was spotless, newly renovated, and admired as the most respectable venue in town.","The seedy theater was shabby and run-down, with neglected rooms and broken fittings.","Seedy describes a disreputable or neglected condition, not a spotless newly renovated one.")],quiz:[Q("seedy.q1","seedy.s1","meaning","A seedy hotel is likely ___.",["shabby and run-down","new and immaculate","a young plant"],"shabby and run-down","This is the figurative adjective sense.","meaning"),Q("seedy.q2","seedy.s1","context","A seedy backstreet bar with broken lights and dirty floors seems ___.",["neglected and disreputable","formal and pristine","quietly religious"],"neglected and disreputable","The description matches seedy's run-down sense.","context"),Q("seedy.q3","seedy.s1","collocation","They avoided the ____ motel with stained carpets and a broken sign.",["seedy","sedate","secular"],"seedy","Seedy motel is a common description of a shabby place.","collocation"),Q("seedy.q4","seedy.s1","distinction","Which building is seedy?",["A neglected theater with broken fittings","A newly restored hall with clean floors","A modern clinic inspected each morning"],"A neglected theater with broken fittings","It is run-down and shabby.","distinction")]});
D("seek",{etymology:E("From Old English secan ‘go in search of, strive after’, from Proto-Germanic *sokjan; English seek means try to find or obtain something, or try to do something.","https://www.etymonline.com/word/seek"),contexts:[C("seek.s1","救援","The hikers sought shelter under a rock ledge when the sudden hailstorm began.","突如其来的冰雹开始时，徒步者到岩壁下寻找避难处。","To seek something is to try to find or get it.","Under a rock ledge identifies the shelter they tried to find.","This is the find-or-obtain sense.") ,C("seek.s2","目標","The council seeks to reduce traffic near the school by widening sidewalks and adding a crossing.","议会试图通过拓宽人行道和增设人行横道来减少学校附近的交通。","To seek to do something is to try or aim to do it.","By introduces the actions intended to achieve the aim.","This is the try-to-do sense.")],mistakes:[M("verb-form","The hikers seeked a dry place during the storm before they found the cave.","The hikers sought a dry place during the storm before they found the cave.","Seek has the irregular past form sought, not seeked.")],quiz:[Q("seek.q1","seek.s1","meaning","If you seek a missing key, you try to ___.",["find it","hide it from everyone","make it heavier"],"find it","This is the find-or-obtain sense.","meaning"),Q("seek.q2","seek.s2","context","The committee seeks to improve bus service means it ___.",["is trying to improve it","has already ended it","is trying to find the committee"],"is trying to improve it","Seek to do means try or aim to do.","context"),Q("seek.q3","seek.s1","verb-form","Choose the correct past tense: Yesterday they ____ shelter.",["sought","seeked","seeking"],"sought","Seek is irregular; its past tense is sought.","verb-form"),Q("seek.q4","seek.s2","distinction","Which sentence uses seek to mean “try to do”?",["The agency seeks to lower emissions.","The child seeks the lost mitten under the bed.","The dog sought its favorite toy."],"The agency seeks to lower emissions.","The infinitive states the action the agency is trying to accomplish.","distinction")]});
})();
