(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,source)=>({origin,prefix:null,root:null,suffix:null,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("select",{etymology:E("From Latin seligere ‘choose’, from se- ‘apart’ + legere ‘gather, choose’; select means choose from a group and, as an adjective, chosen for quality or restricted use.","https://www.etymonline.com/word/select"),contexts:[C("select.s1","招生","The panel selected four candidates from the larger group for final interviews.","评审小组从较大的候选人群体中挑出四人参加最后一轮面试。","To select someone is to choose that person from a group.","From the larger group names the set from which the four were chosen.","This is the verb sense.") ,C("select.s2","商品","The shop keeps a select range of handmade knives made by local craftspeople.","这家商店只经营当地工匠制作的精选手工刀具。","Select as an adjective means chosen for high quality or reserved for a small group.","Made by local craftspeople explains why the range is chosen for quality.","This is the quality-selected adjective use.")],mistakes:[M("meaning","The panel selected no candidates but announced that it had chosen four people from the group.","The panel selected four candidates from the group for the final interviews.","To select means choose; a panel cannot both choose no one and select four people.")],quiz:[Q("select.q1","select.s1","meaning","The editor selected three photographs means the editor ___.",["chose them from a larger group","hid them from the photographer","made them impossible to see"],"chose them from a larger group","This is the verb meaning.","meaning"),Q("select.q2","select.s2","context","A select menu of cheeses is ___.",["a carefully chosen range, often of high quality","every cheese made anywhere","a menu chosen by random accident"],"a carefully chosen range, often of high quality","This is the adjective use for a chosen range.","context"),Q("select.q3","select.s1","collocation","The committee will ____ one proposal for funding.",["select","seethe","sedge"],"select","Select a proposal means choose it from alternatives.","collocation"),Q("select.q4","select.s2","distinction","Which sentence uses select as an adjective?",["The gallery displayed a select collection of rare prints.","The jury selected the winner.","Please select a seat."],"The gallery displayed a select collection of rare prints.","Select modifies collection and describes its chosen quality.","distinction")]});
D("selection",{etymology:E("From Latin selectio ‘a choosing’, from seligere ‘choose’; selection names either the act of choosing or a collection chosen from a wider group.","https://www.etymonline.com/word/selection"),contexts:[C("selection.s1","招聘","The selection of a new director took three months because the board interviewed many applicants.","由于董事会面试了许多申请者，遴选新主任花了三个月。","Selection is the act of choosing someone or something from possibilities.","Interviewed many applicants describes the choice process.","This is the act-of-choosing sense.") ,C("selection.s2","零售","The bookstore has a selection of travel guides from several countries on the front table.","书店前桌上摆着一批来自多个国家的旅行指南。","A selection is a collection chosen from a wider group.","From several countries identifies the variety in the chosen collection.","This is the collection sense.")],mistakes:[M("meaning","The bookstore's selection contained every book ever printed, without anyone choosing any titles.","The bookstore's selection contained a chosen range of travel books from its larger stock.","A selection is chosen from a wider group; it is not necessarily the entire unfiltered set.")],quiz:[Q("selection.q1","selection.s1","meaning","The selection of a team captain is ___.",["the act of choosing one person","a collection of books on a shelf","a unit for measuring time"],"the act of choosing one person","This is the choosing-process sense.","meaning"),Q("selection.q2","selection.s2","context","A store's selection of teas is ___.",["a chosen range of teas","the act of boiling water","a single tea leaf"],"a chosen range of teas","This is a collection of chosen items.","context"),Q("selection.q3","selection.s1","collocation","The board delayed the ____ of a new chair until every candidate was interviewed.",["selection","seepage","seclusion"],"selection","Selection names the process of choosing.","collocation"),Q("selection.q4","selection.s2","distinction","Which uses selection to mean a collection?",["The museum's selection of maps fills one gallery.","The selection of a winner took an hour.","They selected a winner by vote."],"The museum's selection of maps fills one gallery.","Here selection is the set of chosen maps.","distinction")]});
D("selective",{etymology:E("From select + adjective-forming -ive, with select from Latin seligere ‘choose’; selective means careful in choosing or affecting only some members of a group.","https://www.etymonline.com/word/selective"),contexts:[C("selective.s1","招募","The grant is selective: reviewers accept only proposals with strong evidence and a clear public benefit.","这项资助的筛选很严格：评审只接受证据充分、公共效益明确的提案。","Selective can mean careful in choosing and accepting only the best or most suitable.","Only proposals with strong evidence specifies the high standard.","This is the careful-choice adjective sense.") ,C("selective.s2","醫學","The treatment is selective, affecting the targeted cells while leaving most neighboring cells unchanged.","这种治疗具有选择性，只影响目标细胞，而大多数邻近细胞保持不变。","Selective can mean affecting or including certain things but not all.","While contrasts the cells affected with those left unchanged.","This is the limited-effect adjective sense.")],mistakes:[M("meaning","A selective filter affects every item in exactly the same way and excludes nothing.","A selective filter affects only chosen items and leaves others unchanged.","Selective means choosing carefully or affecting only certain members, not all of them equally.")],quiz:[Q("selective.q1","selective.s1","meaning","A selective admissions process ___.",["accepts only applicants meeting chosen standards","accepts every applicant automatically","does not review any applications"],"accepts only applicants meeting chosen standards","This is the careful-choice sense.","meaning"),Q("selective.q2","selective.s2","context","A selective pesticide targets one insect species while leaving other insects unharmed; it ___.",["affects certain organisms, not all","affects every organism equally","chooses the pesticide from a store"],"affects certain organisms, not all","This is the limited-effect sense.","context"),Q("selective.q3","selective.s1","collocation","The scholarship is highly ____ and admits only a few applicants.",["selective","seismic","seedy"],"selective","Selective describes a process that chooses only some applicants.","collocation"),Q("selective.q4","selective.s2","distinction","Which use means “affecting only certain things”?",["A selective filter blocks blue light but passes other colors.","A selective reader carefully chooses which books to buy.","A selective panel chooses the award winner."],"A selective filter blocks blue light but passes other colors.","It affects one kind of light rather than all light.","distinction")]});
D("selenium",{etymology:E("The element was named for Greek Selene, the Moon goddess, by Jöns Jacob Berzelius in 1817 because it was found with tellurium, named for Earth; selenium is element 34.","https://pubchem.ncbi.nlm.nih.gov/element/34"),contexts:[C("selenium.s1","化學","The chemist labeled the sample Se, the symbol for selenium, whose atomic number is 34.","化学家把样品标记为 Se，这是硒的元素符号，原子序数为34。","Selenium is the chemical element with symbol Se and atomic number 34.","Whose atomic number is 34 identifies the element precisely.","This is the chemical-element sense.")],mistakes:[M("meaning","The lab labeled the element selenium with the symbol S and atomic number 16.","The lab labeled selenium with the symbol Se and atomic number 34.","S is sulfur; selenium's symbol is Se and its atomic number is 34.")],quiz:[Q("selenium.q1","selenium.s1","meaning","What is selenium's chemical symbol?",["Se","S","Sn"],"Se","Selenium is represented by Se.","meaning"),Q("selenium.q2","selenium.s1","context","A periodic-table entry lists atomic number 34 and symbol Se; it is ___.",["selenium","sulfur","tin"],"selenium","Those are selenium's identifying details.","context"),Q("selenium.q3","selenium.s1","word-formation","Selenium was named by analogy with tellurium; the name refers to the Greek Moon goddess ___.",["Selene","Athena","Hera"],"Selene","The element's name derives from Greek Selene.","word-formation"),Q("selenium.q4","selenium.s1","distinction","Which statement about selenium is correct?",["It is element 34 and has symbol Se.","It is element 16 and has symbol S.","It is a wetland plant with a triangular stem."],"It is element 34 and has symbol Se.","Element 34 and symbol Se identify selenium.","distinction")]});
D("self",{etymology:E("From Old English self, seolf, from Proto-Germanic *selbaz; as a noun self means the person one is, distinct from others, or one's own interests and advantage.","https://www.etymonline.com/word/self"),contexts:[C("self.s1","個人","After moving abroad, she felt that speaking her first language helped her reconnect with her usual self.","移居国外后，她觉得说母语帮助自己重新找回平常的自我。","The self is the person you are, considered apart from other people.","Her usual self refers to her own identity and character.","This is the personal-identity sense.") ,C("self.s2","利益","By putting self before the team, he reserved the only bonus for himself rather than sharing it.","他把个人利益置于团队之前，把唯一的奖金留给自己而没有与大家分享。","Self can mean one's own interests or advantage.","Before the team contrasts his personal benefit with the group's.","This is the interests sense.")],mistakes:[M("meaning","She used self to mean a committee of strangers, not the individual she herself is.","She used self to mean the individual she is, distinct from other people.","Self as a noun refers to the person one is, not a group of other people.")],quiz:[Q("self.q1","self.s1","meaning","A person's self is ___.",["the person they are as distinct from others","a group of people in one office","a small part of a circle"],"the person they are as distinct from others","This is the identity sense.","meaning"),Q("self.q2","self.s2","context","Putting self-interest aside means ___.",["not acting only for one's own advantage","protecting one's identity from being seen","choosing a second school"],"not acting only for one's own advantage","This is the own-interests sense.","context"),Q("self.q3","self.s1","collocation","After the move, she felt more like her usual ____ again.",["self","seism","selection"],"self","Usual self refers to one's familiar identity or character.","collocation"),Q("self.q4","self.s2","distinction","Which sentence uses self to mean personal advantage?",["He acted for his own self rather than for the team.","She thought about who she was as a person.","He recognized his reflection in the mirror."],"He acted for his own self rather than for the team.","It refers to his own interest or advantage.","distinction")]});D("self-assertion",{etymology:E("A transparent compound of self + assertion, with assertion from Latin asserere ‘claim, affirm’; self-assertion is behavior in which a person confidently expresses a right, opinion, or individuality.","https://www.etymonline.com/word/assertion"),contexts:[C("self-assertion.s1","職場","Her calm self-assertion in the planning meeting ensured that junior designers could explain their concerns.","她在规划会议上平静而坚定地表达意见，使资浅设计师也能说明顾虑。","Self-assertion is behavior in which a person insists on being noticed or having a say.","Ensured that others could speak shows confident expression rather than aggression.","This is the confident-expression sense.")],mistakes:[M("meaning","His self-assertion meant he never voiced an opinion and let others decide every issue for him.","His self-assertion meant he stated his view clearly and asked the group to consider it.","Self-assertion involves making one's presence or opinion known, not remaining entirely silent.")],quiz:[Q("self-assertion.q1","self-assertion.s1","meaning","Self-assertion is ___.",["confidently expressing one's rights or opinions","refusing to speak in every discussion","destroying one's own work"],"confidently expressing one's rights or opinions","This is the noun's meaning.","meaning"),Q("self-assertion.q2","self-assertion.s1","context","At the meeting, her self-assertion helped her ___.",["state her concern clearly and have it considered","hide every idea from the team","take control of a whole country"],"state her concern clearly and have it considered","She confidently made her view known.","context"),Q("self-assertion.q3","self-assertion.s1","word-formation","Self-assertion combines self with the noun ___.",["assertion","secretion","sedimentation"],"assertion","The compound names assertion of oneself.","word-formation"),Q("self-assertion.q4","self-assertion.s1","distinction","Which behavior shows self-assertion without aggression?",["She calmly states her boundary and asks others to respect it.","She says nothing even when her rights are ignored.","She threatens everyone who disagrees."],"She calmly states her boundary and asks others to respect it.","She makes her position clear while remaining calm.","distinction")]});
D("self-concern",{etymology:E("A compound of self + concern, with concern from French concern(er) and Medieval Latin concernere ‘relate to, affect’; self-concern is care directed mainly toward one's own welfare.","https://www.etymonline.com/word/concern"),contexts:[C("self-concern.s1","健康","After several weeks of overwork, taking a rest day showed self-concern about her own health.","连续加班数周后，她休息一天，表现出对自身健康的关照。","Self-concern is care directed mainly toward one's own welfare.","About her own health identifies the person whose welfare is considered.","This is care for one's own well-being.")],mistakes:[M("meaning","His self-concern meant he focused only on other people's needs and ignored his own safety completely.","His self-concern meant he considered his own safety and well-being.","Self-concern directs care toward oneself, not exclusively toward other people.")],quiz:[Q("self-concern.q1","self-concern.s1","meaning","Self-concern is attention to ___.",["one's own welfare","a section of a book","a moving tectonic plate"],"one's own welfare","This is the compound's meaning.","meaning"),Q("self-concern.q2","self-concern.s1","context","She showed self-concern by taking time off to recover, which means she cared about ___.",["her own health","only her colleagues' schedules","the office's furniture"],"her own health","The context directs care toward her welfare.","context"),Q("self-concern.q3","self-concern.s1","word-formation","In self-concern, self identifies the person whose ____ is at issue.",["welfare","earthquake","secrecy"],"welfare","The compound concerns care for one's own welfare.","word-formation"),Q("self-concern.q4","self-concern.s1","distinction","Which action most clearly shows self-concern?",["He checks his own exhaustion and schedules needed rest.","He ignores his health to finish every task for others.","He divides a report into sections."],"He checks his own exhaustion and schedules needed rest.","He attends to his own well-being.","distinction")]});
D("self-control",{etymology:E("A compound of self + control; control came through French from Medieval Latin contrarotulare ‘check against a register’. Self-control is the ability to govern one's feelings and behavior.","https://www.etymonline.com/word/self-control"),contexts:[C("self-control.s1","日常","She showed self-control by pausing before replying to the insulting message and choosing a calm response.","面对侮辱性信息，她先停下来，再选择平静地回复，表现出自制力。","Self-control is the ability to keep feelings and behavior under control, especially when angry or tempted.","Pausing before replying shows restraint in an emotional moment.","This is the emotion-and-behavior regulation sense.")],mistakes:[M("meaning","He showed self-control by immediately shouting every angry thought at his colleague.","He showed self-control by waiting until he was calm before responding to his colleague.","Self-control involves governing an impulse or emotion rather than acting on it immediately.")],quiz:[Q("self-control.q1","self-control.s1","meaning","Self-control helps a person ___.",["manage feelings and behavior","make an earthquake larger","keep a group apart by law"],"manage feelings and behavior","This is the ability to govern one's responses.","meaning"),Q("self-control.q2","self-control.s1","context","She used self-control when she ___.",["waited until calm before answering","sent an angry message at once","bought every item she saw"],"waited until calm before answering","She restrained an immediate emotional reaction.","context"),Q("self-control.q3","self-control.s1","collocation","He needed ____ to resist the temptation to open the gift early.",["self-control","self-destruction","seepage"],"self-control","Resisting temptation is an example of self-control.","collocation"),Q("self-control.q4","self-control.s1","distinction","Which action shows self-control?",["She pauses and chooses not to interrupt while angry.","She says whatever comes to mind immediately.","She ignores all instructions and walks out."],"She pauses and chooses not to interrupt while angry.","She manages her impulse and behavior.","distinction")]});
D("self-defense",{etymology:E("A compound of self + defense, from Old French defense and Latin defensa, from defendere ‘ward off’; self-defense is protecting oneself from attack or the legal right to do so.","https://www.etymonline.com/word/self-defense"),contexts:[C("self-defense.s1","法律","The court considered whether the resident's action was necessary self-defense after an intruder attacked him.","入侵者袭击住户后，法院审查住户的行为是否属于必要的自卫。","Self-defense means protecting yourself from attack, or the legal right to do so.","After an intruder attacked him describes the threat relevant to the claim.","This is the protective and legal sense.")],mistakes:[M("meaning","She claimed self-defense even though nobody threatened or attacked her and she was the one who initiated the assault.","She acted in self-defense when she took proportionate steps to protect herself from an attack.","Self-defense concerns protection against an attack, not initiating an unprovoked assault.")],quiz:[Q("self-defense.q1","self-defense.s1","meaning","Self-defense is action taken to ___.",["protect oneself from an attack","start an unprovoked attack","divide a market into groups"],"protect oneself from an attack","This is the protective sense.","meaning"),Q("self-defense.q2","self-defense.s1","context","A court examines a self-defense claim to decide whether someone ___.",["acted to protect themself from an attack","secretly bought a used bicycle","controlled another region"],"acted to protect themself from an attack","The term can refer to the legal right to defend oneself.","context"),Q("self-defense.q3","self-defense.s1","collocation","The law recognizes a right to act in ____ when faced with an attack.",["self-defense","self-importance","self-perception"],"self-defense","Act in self-defense means protect oneself from attack.","collocation"),Q("self-defense.q4","self-defense.s1","distinction","Which case most clearly involves self-defense?",["A person protects themself from an ongoing assault.","A person attacks a stranger without warning.","A person controls anger during a meeting."],"A person protects themself from an ongoing assault.","The action responds to an attack and protects the person.","distinction")]});
D("self-destruction",{etymology:E("A compound of self + destruction, with destruction from Latin destruere ‘pull down, demolish’; self-destruction is destroying oneself or a process of ruining one's own life, health, or work.","https://www.etymonline.com/word/self-destruction"),contexts:[C("self-destruction.s1","職涯","The manager's repeated refusal to hear feedback led to the self-destruction of a once-promising career.","经理屡次拒绝听取反馈，最终毁掉了原本前景良好的事业。","Self-destruction can mean a process by which a person ruins their own life, work, or prospects.","Repeated refusal and led to show the person's choices causing the decline.","This is the figurative self-ruining sense.")],mistakes:[M("meaning","The project avoided self-destruction by ignoring all warnings until its funding and staff disappeared.","The project moved toward self-destruction by ignoring warnings until its funding and staff disappeared.","Self-destruction describes a process of ruining one's own work, so ignoring warnings can cause it rather than prevent it.")],quiz:[Q("self-destruction.q1","self-destruction.s1","meaning","A pattern of self-destruction can ___.",["ruin a person's own work or prospects","make every plan succeed automatically","protect someone from a sudden attack"],"ruin a person's own work or prospects","This is the figurative sense of ruining oneself.","meaning"),Q("self-destruction.q2","self-destruction.s1","context","A leader's repeated sabotage of the team caused the self-destruction of the project, meaning the project ___.",["was ruined through the leader's own actions","was saved by careful planning","became a young plant"],"was ruined through the leader's own actions","The person's behavior undermined their own project.","context"),Q("self-destruction.q3","self-destruction.s1","word-formation","Self-destruction combines self with destruction, so it describes destruction directed toward ___.",["oneself or one's own prospects","a river's sediment","another person's house only"],"oneself or one's own prospects","The compound marks the person or work as being ruined by its own course.","word-formation"),Q("self-destruction.q4","self-destruction.s1","distinction","Which situation best fits figurative self-destruction?",["A business repeatedly rejects sound advice and loses its customers and staff.","A company improves after listening to its staff.","A gardener removes seeds from a pepper."],"A business repeatedly rejects sound advice and loses its customers and staff.","Its own repeated choices ruin its prospects.","distinction")]});D("self-discipline",{etymology:E("A compound of self + discipline; discipline comes through Latin disciplina ‘instruction, training’, from discipulus ‘pupil’. Self-discipline is regulating one's conduct to meet a standard.","https://www.etymonline.com/word/self-discipline"),contexts:[C("self-discipline.s1","學習","His self-discipline helped him study for an hour each evening even when no one checked his progress.","即使没有人检查进度，他仍凭自律坚持每天晚上学习一小时。","Self-discipline is control of one's feelings and behavior in order to meet a standard.","Even when no one checked shows the effort is self-imposed.","This is the self-regulation noun.")],mistakes:[M("meaning","Her self-discipline meant she abandoned the study plan whenever the work became difficult.","Her self-discipline meant she kept to the study plan even when the work became difficult.","Self-discipline is control that helps someone meet a goal, not abandoning it at the first difficulty.")],quiz:[Q("self-discipline.q1","self-discipline.s1","meaning","Self-discipline is the ability to ___.",["control one's behavior to meet a standard","make other people obey every order","keep a liquid from settling"],"control one's behavior to meet a standard","This is the noun's definition.","meaning"),Q("self-discipline.q2","self-discipline.s1","context","She showed self-discipline by practicing piano daily without reminders, which means she ___.",["held herself to the practice routine","waited for others to force her","stopped practicing whenever she was alone"],"held herself to the practice routine","The routine is maintained through her own regulation.","context"),Q("self-discipline.q3","self-discipline.s1","collocation","Finishing a long course often requires ____.",["self-discipline","seepage","self-destruction"],"self-discipline","A sustained course requires control of one's behavior.","collocation"),Q("self-discipline.q4","self-discipline.s1","distinction","Which student shows self-discipline?",["One who follows a revision plan even without supervision","One who studies only when someone threatens punishment","One who never sets a learning goal"],"One who follows a revision plan even without supervision","The student regulates their own effort toward a standard.","distinction")]});
D("self-disciplined",{etymology:E("A compound of self + disciplined, the past participle of discipline; discipline comes from Latin disciplina ‘training’. Self-disciplined describes someone who makes themself work or behave as required.","https://www.etymonline.com/word/self-disciplined"),contexts:[C("self-disciplined.s1","工作","The self-disciplined editor finished a careful review each morning before checking social media.","这位自律的编辑每天早上先认真校对，再查看社交媒体。","Self-disciplined describes someone who makes themself work or behave as required.","Before checking social media shows the editor follows a chosen work routine.","This is the adjective for self-directed discipline.")],mistakes:[M("meaning","The self-disciplined editor ignored every deadline and did no work unless a supervisor stood nearby.","The self-disciplined editor met deadlines and completed the review without needing a supervisor nearby.","A self-disciplined person follows required behavior through their own control.")],quiz:[Q("self-disciplined.q1","self-disciplined.s1","meaning","A self-disciplined person ___.",["makes themself follow a useful routine","needs constant reminders to do any task","avoids every standard"],"makes themself follow a useful routine","This is the adjective's meaning.","meaning"),Q("self-disciplined.q2","self-disciplined.s1","context","The self-disciplined runner trains on schedule even when it is cold, meaning the runner ___.",["keeps to the plan through personal effort","waits for a coach to carry them","changes the goal every day"],"keeps to the plan through personal effort","The runner maintains a chosen routine independently.","context"),Q("self-disciplined.q3","self-disciplined.s1","word-formation","Self-disciplined describes discipline directed by ___.",["the person themself","a weather event","a school section"],"the person themself","The self- compound signals personal regulation.","word-formation"),Q("self-disciplined.q4","self-disciplined.s1","distinction","Which worker is self-disciplined?",["She completes the required report on time without reminders.","He ignores the task until a supervisor arrives.","They leave every assignment unfinished."],"She completes the required report on time without reminders.","She makes herself meet the work requirement.","distinction")]});
D("self-esteem",{etymology:E("A compound of self + esteem; esteem comes through Old French estimer from Latin aestimare ‘value, appraise’. Self-esteem is respect for oneself and confidence in one's own worth.","https://www.etymonline.com/word/self-esteem"),contexts:[C("self-esteem.s1","教育","The teacher praised the student's careful effort rather than only the score, helping build realistic self-esteem.","老师肯定了学生认真付出的过程，而不只看分数，帮助其建立现实而健康的自我价值感。","Self-esteem is respect for oneself and confidence in one's worth.","Praised effort rather than only score supports worth beyond one result.","This is the self-worth and confidence noun.")],mistakes:[M("meaning","A person's self-esteem is strong only when that person believes they have no value and deserve no respect.","A person's self-esteem includes recognizing their own worth and expecting respectful treatment.","Self-esteem is respect for one's own value, not a belief that one has none.")],quiz:[Q("self-esteem.q1","self-esteem.s1","meaning","Self-esteem is ___.",["respect for oneself and confidence in one's worth","a need to control other people","a young tree in a nursery"],"respect for oneself and confidence in one's worth","This is the noun's definition.","meaning"),Q("self-esteem.q2","self-esteem.s1","context","After making one mistake, she kept a healthy self-esteem because she ___.",["still recognized her abilities and worth","decided she was worthless","expected everyone to praise every action"],"still recognized her abilities and worth","Self-esteem is a sense of personal worth, not perfection.","context"),Q("self-esteem.q3","self-esteem.s1","collocation","Supportive feedback can help a child develop healthy ____.",["self-esteem","self-segregation","seepage"],"self-esteem","Healthy self-esteem means confidence in one's worth.","collocation"),Q("self-esteem.q4","self-esteem.s1","distinction","Which statement best reflects self-esteem?",["I have worth even when I make a mistake.","I have no value unless I am perfect.","I am more important than every other person."],"I have worth even when I make a mistake.","It expresses confidence in one's own value without claiming superiority.","distinction")]});
D("self-explanatory",{etymology:E("A compound of self + explanatory; explain came through Latin explanare ‘make plain, level’, from ex- + planus ‘flat’. Self-explanatory means clear without further comment.","https://www.etymonline.com/word/self-explanatory"),contexts:[C("self-explanatory.s1","說明書","The chart's labels were self-explanatory, so readers could understand the symbols without a separate key.","图表标签一目了然，读者不用另查图例也能看懂符号。","Self-explanatory means clear from itself, making further comment unnecessary.","Without a separate key describes the lack of extra explanation needed.","This is the clarity adjective.")],mistakes:[M("meaning","The self-explanatory diagram could not be understood until the author gave a long private lecture about every symbol.","The self-explanatory diagram could be understood without a separate lecture.","Self-explanatory describes something clear without additional explanation.")],quiz:[Q("self-explanatory.q1","self-explanatory.s1","meaning","A self-explanatory sign is one that ___.",["is clear without extra explanation","has no words or symbols at all","must be hidden from readers"],"is clear without extra explanation","This is the adjective's definition.","meaning"),Q("self-explanatory.q2","self-explanatory.s1","context","The unlabeled-looking icon was self-explanatory because everyone understood it immediately, so it ___.",["needed no further explanation","required a long manual","was impossible to interpret"],"needed no further explanation","Its meaning was clear from the icon itself.","context"),Q("self-explanatory.q3","self-explanatory.s1","collocation","The form's instructions were so ____ that applicants needed no help.",["self-explanatory","seismic","sedentary"],"self-explanatory","The instructions explained themselves clearly.","collocation"),Q("self-explanatory.q4","self-explanatory.s1","distinction","Which note is self-explanatory?",["“Press the green button to print” beside a clearly marked green button","An unexplained code with no key or instructions","A chart that only its author can interpret"],"“Press the green button to print” beside a clearly marked green button","The instruction and label make the action clear.","distinction")]});
D("self-governing",{etymology:E("A compound of self + governing, with govern from Old French governer and Latin gubernare ‘steer, direct’; self-governing describes a group or region that can make its own laws and decisions.","https://www.etymonline.com/word/self-governing"),contexts:[C("self-governing.s1","地方治理","The island became self-governing, with an elected council making local laws while national defense remained shared.","该岛成为自治地区，由民选议会制定当地法律，同时与国家共享国防事务。","A self-governing region has the right to make its own laws and decisions.","With an elected council making local laws shows the region's own decision-making.","This is the political-autonomy adjective.")],mistakes:[M("meaning","The region was self-governing even though an outside office made every local law and decision for it.","The region was self-governing because its own elected council made local laws and decisions.","Self-governing means a group or region exercises its own governing authority, not that all decisions are imposed externally.")],quiz:[Q("self-governing.q1","self-governing.s1","meaning","A self-governing region can ___.",["make its own laws and decisions","only follow rules written elsewhere","not choose any local officials"],"make its own laws and decisions","This is the adjective's political meaning.","meaning"),Q("self-governing.q2","self-governing.s1","context","An elected local council passes laws for its own island; the island is ___.",["self-governing","sedimentary","secondhand"],"self-governing","The council exercises the region's own decision-making.","context"),Q("self-governing.q3","self-governing.s1","word-formation","Self-governing combines self with governing, which here means ___.",["directing one's own affairs","hiding a private fact","measuring an earthquake"],"directing one's own affairs","The compound indicates government by the group itself.","word-formation"),Q("self-governing.q4","self-governing.s1","distinction","Which community is self-governing?",["Its elected members set local rules for the community.","An outside administrator makes every local decision.","The community has no authority over its affairs."],"Its elected members set local rules for the community.","Its own members make decisions for the community.","distinction")]});D("self-government",{etymology:E("A compound of self + government, with govern from Old French governer and Latin gubernare ‘steer, direct’; self-government is the right or practice of a community ruling itself.","https://www.etymonline.com/word/self-government"),contexts:[C("self-government.s1","自治","The constitution granted the province self-government, allowing residents to elect leaders and decide local policies.","宪法赋予该省自治权，使居民可以选举领导人并决定地方政策。","Self-government is the right or practice of a community governing itself.","Elect leaders and decide local policies describe the community's own rule.","This is the political autonomy noun.")],mistakes:[M("meaning","The province achieved self-government when an outside governor began making every local decision without consulting residents.","The province achieved self-government when residents elected their own leaders and made local decisions.","Self-government means a community rules itself, rather than being governed entirely by an outside authority.")],quiz:[Q("self-government.q1","self-government.s1","meaning","Self-government gives a community the ability to ___.",["rule itself","be ruled entirely by outsiders","hide a document"],"rule itself","This is the noun's definition.","meaning"),Q("self-government.q2","self-government.s1","context","Residents elect a local council and decide local policies; this is ___.",["self-government","seclusion","seepage"],"self-government","The community governs its own affairs.","context"),Q("self-government.q3","self-government.s1","collocation","The constitution recognized the region's right to ____.",["self-government","self-destruction","self-concern"],"self-government","The phrase names a community's right to rule itself.","collocation"),Q("self-government.q4","self-government.s1","distinction","Which arrangement is an example of self-government?",["A community elects its own council to decide local matters.","An outside office appoints every local official.","Residents are not allowed to take part in any decision."],"A community elects its own council to decide local matters.","The community makes its own governing decisions.","distinction")]});
D("self-importance",{etymology:E("A compound of self + importance, with important from Latin importare ‘be significant, matter’; self-importance is an often exaggerated opinion of one's own status.","https://www.etymonline.com/word/self-importance"),contexts:[C("self-importance.s1","職場","His self-importance showed when he expected the whole meeting to stop so everyone could hear his minor update.","他认为自己举足轻重，竟要求整场会议停下来听他汇报一件小事。","Self-importance is a high, often ridiculous, opinion of one's own status.","Expected the whole meeting to stop for a minor update shows the inflated status he assumes.","This is the excessive self-estimation noun.")],mistakes:[M("meaning","Her self-importance meant she saw herself as no more significant than any other person and never demanded special attention.","Her self-importance meant she saw herself as unusually significant and expected special attention.","Self-importance is an inflated sense of one's own status, not a modest view of oneself.")],quiz:[Q("self-importance.q1","self-importance.s1","meaning","Self-importance is ___.",["an exaggerated view of one's own status","confidence that one is worthless","a plant growing from a seed"],"an exaggerated view of one's own status","This is the noun's meaning.","meaning"),Q("self-importance.q2","self-importance.s1","context","He showed self-importance by demanding that every colleague wait for his late arrival, meaning he ___.",["expected special treatment","respected everyone's time equally","was concerned only with his health"],"expected special treatment","He acts as though his status deserves unusual priority.","context"),Q("self-importance.q3","self-importance.s1","collocation","The speaker's ____ made her dismiss every question as beneath her.",["self-importance","self-defense","seismicity"],"self-importance","An inflated view of one's status can lead to dismissive behavior.","collocation"),Q("self-importance.q4","self-importance.s1","distinction","Which behavior suggests self-importance?",["He expects others to interrupt their work whenever he wants attention.","She listens carefully to each person's contribution.","They share credit fairly with the team."],"He expects others to interrupt their work whenever he wants attention.","He expects his own status to outrank everyone else's needs.","distinction")]});
D("self-perception",{etymology:E("A compound of self + perception, with perception from Latin perceptio ‘a receiving, understanding’, from percipere ‘take in’; self-perception is a person's view of who they are.","https://www.etymonline.com/word/self-perception"),contexts:[C("self-perception.s1","心理","Her self-perception as a beginner changed after she reviewed the expert-level work she had completed.","回顾自己完成的专家级工作后，她对自己仍是初学者的看法发生了变化。","Self-perception is a person's view of who they are and what they can do.","Changed after reviewing completed work shows her view of herself shifting with evidence.","This is the view-of-oneself noun.")],mistakes:[M("meaning","His self-perception was his neighbor's private opinion of him, not his own view of who he was.","His self-perception was his own view of who he was and what he could do.","Self-perception is a person's own view of themself, not another person's opinion.")],quiz:[Q("self-perception.q1","self-perception.s1","meaning","Self-perception is ___.",["a person's view of who they are","a legal right to defend oneself","a tool that records earthquakes"],"a person's view of who they are","This is the noun's definition.","meaning"),Q("self-perception.q2","self-perception.s1","context","After learning new skills, her self-perception changed because she ___.",["viewed her own abilities differently","changed the opinions of every neighbor","divided herself into sections"],"viewed her own abilities differently","Self-perception concerns how someone sees themself.","context"),Q("self-perception.q3","self-perception.s1","word-formation","Self-perception combines self with perception, meaning a view or understanding of ___.",["oneself","an earthquake","a second owner"],"oneself","The compound makes the person themself the object of perception.","word-formation"),Q("self-perception.q4","self-perception.s1","distinction","Which statement expresses someone's self-perception?",["I see myself as capable of learning the new role.","My colleague thinks I should learn the new role.","The committee chose someone for the role."],"I see myself as capable of learning the new role.","The statement describes the speaker's view of themself.","distinction")]});
D("self-reliant",{etymology:E("A compound of self + reliant, with rely from Old French relier ‘bind, fasten’; self-reliant describes someone able to provide for themself and handle problems without depending on others.","https://www.etymonline.com/word/self-reliant"),contexts:[C("self-reliant.s1","戶外","The self-reliant hikers carried a map, water filter, and repair kit so they could manage minor problems on the remote trail.","这些独立自主的徒步者带了地图、滤水器和修理工具，以便在偏远小径上自行处理小问题。","Self-reliant means able to provide for yourself and deal with problems on your own.","The equipment lets the hikers manage without immediate outside help.","This is the independent problem-solving adjective.")],mistakes:[M("meaning","The self-reliant camper depended on strangers to carry every item and solve each small problem.","The self-reliant camper carried needed supplies and handled ordinary problems independently.","Self-reliant describes being able to manage without depending on others for every need.")],quiz:[Q("self-reliant.q1","self-reliant.s1","meaning","A self-reliant person is able to ___.",["manage needs and problems independently","avoid making any decision","rule a whole country"],"manage needs and problems independently","This is the adjective's meaning.","meaning"),Q("self-reliant.q2","self-reliant.s1","context","The self-reliant traveler packed tools and a map because she ___.",["could handle ordinary problems on her own","expected a guide to carry everything","wanted to remain in one place forever"],"could handle ordinary problems on her own","The supplies support independent problem-solving.","context"),Q("self-reliant.q3","self-reliant.s1","collocation","The remote team became more ____ after learning to repair its equipment.",["self-reliant","self-important","sedimentary"],"self-reliant","It can manage its needs without outside help.","collocation"),Q("self-reliant.q4","self-reliant.s1","distinction","Which person is self-reliant?",["She fixes a simple flat tire using the tools she brought.","He waits for someone else to make every small decision.","They refuse to learn any practical skill."],"She fixes a simple flat tire using the tools she brought.","She can address the problem independently.","distinction")]});
D("self-respect",{etymology:E("A compound of self + respect, with respect from Latin respectus ‘regard, consideration’; self-respect is pride and confidence in one's value that supports expecting respectful treatment.","https://www.etymonline.com/word/self-respect"),contexts:[C("self-respect.s1","人際","She kept her self-respect by calmly refusing to accept insults as a condition of staying on the project.","她平静地拒绝把忍受侮辱当作留在项目中的条件，维护了自尊。","Self-respect is pride and confidence in one's own value, including expecting respectful treatment.","Calmly refusing insults shows a boundary based on her sense of worth.","This is the dignity-and-worth noun.")],mistakes:[M("meaning","He showed self-respect by agreeing that he deserved no basic courtesy and should accept every insult.","He showed self-respect by recognizing his worth and asking others to treat him with basic courtesy.","Self-respect includes valuing oneself and expecting respectful treatment, not accepting every insult.")],quiz:[Q("self-respect.q1","self-respect.s1","meaning","Self-respect is ___.",["confidence in one's own value and dignity","an inflated belief that one outranks everyone","a habit of hiding all information"],"confidence in one's own value and dignity","This is the noun's definition.","meaning"),Q("self-respect.q2","self-respect.s1","context","She maintained self-respect by setting a calm boundary, meaning she ___.",["recognized her worth and expected respectful treatment","demanded that everyone admire her","refused to respect anyone else"],"recognized her worth and expected respectful treatment","Self-respect supports personal dignity and boundaries.","context"),Q("self-respect.q3","self-respect.s1","collocation","He left the unfair arrangement to preserve his ____.",["self-respect","self-destruction","secretion"],"self-respect","Preserve one's self-respect means maintain one's sense of dignity.","collocation"),Q("self-respect.q4","self-respect.s1","distinction","Which action reflects self-respect without self-importance?",["She asks to be treated fairly while listening respectfully to others.","He demands special treatment because he thinks everyone is beneath him.","They accept abuse because they believe they have no worth."],"She asks to be treated fairly while listening respectfully to others.","Self-respect affirms one's dignity without claiming superiority.","distinction")]});
})();